cd /tmp/claude-1000/-mnt-data-projects-discourse-graph/eade768f-020e-4915-86f1-5f3a22e40081/scratchpad/linear && cat > q1.json <<'EOF'
{"query":"query { projectMilestone(id: \"ef992227-fafc-4687-ae46-ac9080dba637\") { name issues(first: 100) { nodes { identifier title sortOrder subIssueSortOrder state { name } assignee { name } parent { identifier } children { nodes { identifier title state { name } projectMilestone { name } } } relations { nodes { type relatedIssue { identifier title } } } inverseRelations { nodes { type issue { identifier title } } } attachments { nodes { title url sourceType } } } } } }"}
EOF
curl -s -H "Authorization: $LINEAR_API_KEY" -H "Content-Type: application/json" -X POST https://api.linear.app/graphql -d @q1.json > r1.json && python3 -I -c "
import json
d=json.load(open('r1.json'))
if 'errors' in d: print(d['errors']); raise SystemExit
nodes=d['data']['projectMilestone']['issues']['nodes']
nodes.sort(key=lambda n:n['sortOrder'])
for n in nodes:
    print(f\"{n['sortOrder']:>12.2f} {n['identifier']:9} [{n['state']['name']}] {n['title']}  (assignee={n['assignee']['name'] if n['assignee'] else None}, parent={n['parent']['identifier'] if n['parent'] else None})\")
    for c in n['children']['nodes']:
        print(f\"{'':22}child {c['identifier']} [{c['state']['name']}] ms={c['projectMilestone']['name'] if c['projectMilestone'] else None} {c['title']}\")
    for r in n['relations']['nodes']:
        print(f\"{'':22}rel {r['type']} -> {r['relatedIssue']['identifier']} {r['relatedIssue']['title']}\")
    for r in n['inverseRelations']['nodes']:
        print(f\"{'':22}inv {r['type']} <- {r['issue']['identifier']} {r['issue']['title']}\")
    for a in n['attachments']['nodes']:
        print(f\"{'':22}att {a['sourceType']} {a['title']} {a['url']}\")
"

