cd /tmp/claude-1000/-mnt-data-projects-discourse-graph/eade768f-020e-4915-86f1-5f3a22e40081/scratchpad/linear && python3 -I - <<'EOF'
import json, os, subprocess
ids = ["ENG-2412","ENG-2005","ENG-2413","ENG-2165","ENG-2166","ENG-2091","ENG-2061","ENG-1986","ENG-1794","ENG-1824","ENG-1823","FEE-891","FEE-890","ENG-1985","ENG-2045","ENG-2055","ENG-1866","ENG-2394","ENG-2429","ENG-1822"]
out = {}
for i in ids:
    q = {"query": 'query($id:String!){ issue(id:$id){ identifier title description state{name} assignee{name} comments(first:60){ nodes{ id body createdAt user{name} parent{id} } } } }', "variables": {"id": i}}
    r = subprocess.run(["curl","-s","-H",f"Authorization: {os.environ['LINEAR_API_KEY']}","-H","Content-Type: application/json","-X","POST","https://api.linear.app/graphql","-d",json.dumps(q)],capture_output=True,text=True)
    d = json.loads(r.stdout)
    if 'errors' in d:
        print(i, d['errors'][0]['message']); continue
    out[i] = d['data']['issue']
json.dump(out, open('issues.json','w'), indent=1)
for i,v in out.items():
    if not v: print(i,"None"); continue
    print(f"{i}: {v['title']} [{v['state']['name']}] desc={len(v['description'] or '')} chars, comments={len(v['comments']['nodes'])}")
EOF

