import { ridToSpaceUriAndLocalId, spaceUriAndLocalIdToRid } from "./rid";
import type { Enums, Json, Tables } from "../dbTypes";

type SharedConcept = Pick<
  Tables<"my_concepts">,
  | "is_schema"
  | "last_modified"
  | "schema_id"
  | "source_local_id"
